/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import java.util.ArrayList;import java.util.List;import page2020.core.App;import page2020.core.Box;import page2020.core.Page;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Content;import page2020.view.H5;import page2020.view.bs4.B4border;import page2020.view.bs4.B4button;import page2020.view.bs4.B4element;import page2020.view.bs4.B4show.AlignSelf;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4text.TextX;import page2020.view.css3.C3color.Red;import page2020.view.css3.C3color.White;import page2020.view.css3.C3show.Cursor;import page2020.view.css3.C3show.Overflow;import page2020.view.css3.C3show.Position;import page2020.view.css3.C3show.Visible;public class Ubox extends B4element {	public static void selector(Page page) {		page.selector("body>div[data-type='ubox']",			C3.show.visibility(Visible.hidden),			C3.show.position(Position.fixed),			C3.show.zIndex(1),			C3.bg("rgba(0,0,0,0.5)"),			C3.box.left("0"),			C3.box.top("0"),			C3.width("100%"),			C3.height("100%")		);		page.selector("body>div[data-type='ubox'] span[data-close]", C3.show.cursor(Cursor.pointer)	);			page.selector("body>div[data-type='ubox'] span[data-close]>svg:hover", C3.color(Red.Red));		page.selector("body>div[data-type='ubox'] button[data-name]",			C3.text.whiteSpace(false),			C3.padding("0.25rem 2.5rem"), 			C3.margin("0.25rem 0.5rem"), 			C3.border.radius("1rem")		);	}	public Ubox(String name, Box argument, Content<?>... contents) {		super();		super.name(name).data(PageKey.type, "ubox");		B4element working = this.working(argument);		if (contents.length > 0) {			B4element elements = (B4element) working.get(0);			elements.append(contents);		}		Func func = this.function(name);		if (func != null && func.getButtons().size() > 0) {			B4element buttons = (B4element) working.get(1);			buttons.pt(2).cssClass(TextX.center)				.append(this.buttons(func.getButtons()));		}		super.cssClass(D.flex).append(			B4.container(true).cssClass(AlignSelf.center).append(				B4.row(true).append(					B4.col(argument.getGaps()),					B4.col(argument.getDevices()).append(this.header(), working),					B4.col(argument.getGaps())		)));	}	private Func function(String name) {		Func func = App.function(name);		if (func != null) {			return func;		}		func = App.function(name + "*");		if (func != null) {			return func;		}		return null;	}	private B4element header() {		return B4.element()			.cssClass(TextX.right)			.css(C3.height("2rem"))			.append(				H5.span().data("close", "").css(C3.color(White.White)).append(					H5.icon("times").size("2x")				)			);	}	private B4element working(Box argument) {		B4element boxContent = B4.element().p(1).data(PageKey.type, "box-content");		String height = argument.getHeight();		if (EmptyUtil.not(height)) {			if (height.endsWith("%")) {				boxContent.data("height", height);			} else {				boxContent.css(C3.box.maxHeight(height));			}			boxContent.css(C3.show.overflowX(Overflow.hidden), C3.show.overflowY(Overflow.auto));		}		B4element boxButton = B4.element().data(PageKey.type, "box-button");		return B4.element()			.px(3).pt(3).pb(2)			.cssClass(B4border.round)			.css(C3.bg(White.White))			.append(boxContent, boxButton);	}	private List<Content<?>> buttons(List<String> btnNames) {		List<Content<?>> list = new ArrayList<Content<?>>();		for (String btnName : btnNames) {			B4button button = App.button(btnName);			list.add(button);		}		return list;	}}